export interface ConnectorConfig {
  baseId: string;
  tableName: string;
  recordId: string;
  apiKey: string;
  fetch?: typeof fetch;
}

export interface JotformSubmission {
  email: string;
  first_name?: string;
  last_name?: string;
  phone?: string;
  address?: string;
}

export interface HandleResult {
  recordId: string;
  updatedFields: string[];
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

function buildPatchFields(payload: JotformSubmission): Record<string, string> {
  const fields: Record<string, string> = {};
  if (isNonEmptyString(payload.first_name)) fields['First Name'] = payload.first_name.trim();
  if (isNonEmptyString(payload.last_name)) fields['Last Name'] = payload.last_name.trim();
  if (isNonEmptyString(payload.phone)) fields['Phone'] = payload.phone.trim();
  if (isNonEmptyString(payload.address)) fields['Address'] = payload.address.trim();
  return fields;
}

export async function handle(payload: JotformSubmission, config: ConnectorConfig): Promise<HandleResult> {
  if (!payload.email || typeof payload.email !== 'string' || payload.email.trim().length === 0) {
    throw new Error('Missing required field: email');
  }

  const { baseId, tableName, recordId, apiKey, fetch: customFetch } = config;
  const fetchFn = customFetch ?? fetch;

  const patchFields = buildPatchFields(payload);
  if (Object.keys(patchFields).length === 0) {
    return { recordId, updatedFields: [] };
  }

  const url = `https://api.airtable.com/v0/${encodeURIComponent(baseId)}/${encodeURIComponent(tableName)}/${encodeURIComponent(recordId)}`;
  const response = await fetchFn(url, {
    method: 'PATCH',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ fields: patchFields }),
  });

  if (!response.ok) {
    throw new Error(`Airtable PATCH failed: ${response.status} ${response.statusText} for ${url}`);
  }

  const updatedFields = Object.keys(patchFields);
  return { recordId, updatedFields };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, JotformSubmission } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      recordId: 'recABC123',
      apiKey: 'test-api-key',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.recordId).toBe('recABC123');
    expect(result.updatedFields).toEqual(['First Name', 'Last Name', 'Phone', 'Address']);
  });
});

describe('handle', () => {
  it('maps non-empty Jotform fields to Airtable fields in PATCH body', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('PATCH');
      expect(req.url).toContain('/appTestBase/TestTable/recABC123');
      expect(req.headers.get('authorization')).toBe('Bearer test-api-key');
      const body = req.json as { fields: Record<string, string> };
      expect(body.fields).toEqual({
        'First Name': 'John',
        'Last Name': 'Doe',
        'Phone': '555-123-4567',
        'Address': '123 Main St',
      });
      return jsonResponse({ id: 'recABC123', fields: body.fields, createdTime: '2024-01-01T12:00:00.000Z' });
    });

    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      recordId: 'recABC123',
      apiKey: 'test-api-key',
      fetch,
    };

    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: 'John',
      last_name: 'Doe',
      phone: '555-123-4567',
      address: '123 Main St',
    };

    const result = await handle(payload, config);
    expect(result.updatedFields).toEqual(['First Name', 'Last Name', 'Phone', 'Address']);
    expect(calls.length).toBe(1);
  });

  it('omits empty Jotform fields from PATCH body', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const body = req.json as { fields: Record<string, string> };
      expect(body.fields).toEqual({ 'First Name': 'Jane' });
      return jsonResponse({ id: 'recABC123', fields: body.fields, createdTime: '2024-01-01T12:00:00.000Z' });
    });

    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      recordId: 'recABC123',
      apiKey: 'test-api-key',
      fetch,
    };

    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: 'Jane',
      last_name: '',
      phone: '   ',
      address: undefined,
    };

    const result = await handle(payload, config);
    expect(result.updatedFields).toEqual(['First Name']);
    expect(calls.length).toBe(1);
  });

  it('throws when email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      recordId: 'recABC123',
      apiKey: 'test-api-key',
      fetch,
    };

    const payload = { first_name: 'John' } as unknown as JotformSubmission;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email');
  });

  it('throws on non-2xx response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      recordId: 'recABC123',
      apiKey: 'test-api-key',
      fetch,
    };

    const payload: JotformSubmission = { email: 'user@example.com', first_name: 'John' };
    await expect(handle(payload, config)).rejects.toThrow('Airtable PATCH failed: 401 Unauthorized for https://api.airtable.com/v0/appTestBase/TestTable/recABC123');
    expect(calls.length).toBe(1);
  });

  it('returns empty updatedFields when all Jotform fields are empty', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ id: 'recABC123', fields: {}, createdTime: '2024-01-01T12:00:00.000Z' }));
    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      recordId: 'recABC123',
      apiKey: 'test-api-key',
      fetch,
    };

    const payload: JotformSubmission = { email: 'user@example.com' };
    const result = await handle(payload, config);
    expect(result.updatedFields).toEqual([]);
    expect(calls.length).toBe(0);
  });

  it('uses injected fetch over global fetch', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ id: 'recABC123', fields: req.json, createdTime: '2024-01-01T12:00:00.000Z' }));
    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      recordId: 'recABC123',
      apiKey: 'test-api-key',
      fetch,
    };

    const payload: JotformSubmission = { email: 'user@example.com', first_name: 'Test' };
    await handle(payload, config);
    expect(calls.length).toBe(1);
  });
});

